async (page) => {
  const out = { blocked: [], allowed: 0 };
  const ctx = page.context();
  await ctx.route('**/*', async (route) => {
    try {
      const u = new URL(route.request().url());
      const ok = u.protocol === 'http:' && u.port === '5174' &&
        ['localhost', '127.0.0.1', '::1'].includes(u.hostname) && !u.username && !u.password;
      if (ok) { out.allowed++; return await route.continue(); }
      if (!out.blocked.includes(u.origin)) out.blocked.push(u.origin);
      return await route.abort();
    } catch (e) { return await route.abort(); }
  });
  await page.setViewportSize({ width: 1280, height: 720 });
  await page.goto('http://localhost:5174/', { waitUntil: 'domcontentloaded' });
  const finalUrl = new URL(page.url());
  out.finalOrigin = finalUrl.origin;
  if (finalUrl.protocol !== 'http:' || finalUrl.hostname !== 'localhost' || finalUrl.port !== '5174') {
    return JSON.stringify({ ABORT: 'origin mismatch', out });
  }
  await page.waitForSelector('header', { timeout: 15000 });
  await page.waitForSelector('[role="application"]', { timeout: 15000 });
  const grid = page.locator('[role="application"]');
  out.gridAriaLabel = await grid.getAttribute('aria-label');
  out.gridCount = await page.locator('[role="application"]').count();
  out.binCount = await page.locator('[data-bin-id]').count();
  out.stagingCount = await page.locator('[data-staging-bin-id]').count();
  out.stashPresent = await page.locator('[data-stash]').count();
  // sidebar stepper controls
  const sidebar = page.locator('[data-sidebar]');
  out.sidebarCount = await sidebar.count();
  const labels = await page.locator('[aria-label]').evaluateAll((els) =>
    els.map((e) => ({ label: e.getAttribute('aria-label'), tag: e.tagName.toLowerCase(), role: e.getAttribute('role') }))
       .filter((e) => /drawer|width|depth|grid|stash|staging/i.test(e.label))
  );
  out.matchingAriaLabels = labels;
  return JSON.stringify(out, null, 1);
}
EOF
