async (page) => {
  const ALLOWED = ['localhost:5174', '127.0.0.1:5174', '[::1]:5174'];
  const authorityOf = (u) => { const m = /^http:\/\/([^/?#]*)([/?#].*)?$/.exec(u); return m ? m[1] : null; };
  const isAllowed = (u) => ALLOWED.indexOf(authorityOf(u)) !== -1;
